<?php
class Host extends Model{public function all(){return $this->query('SELECT hosts.*,users.email FROM hosts JOIN users ON hosts.user_id=users.user_id ORDER BY host_id DESC')->fetchAll();}public function find($id){return $this->query('SELECT * FROM hosts WHERE host_id=?',[$id])->fetch();}public function create($d){return $this->query('INSERT INTO hosts(user_id,company_name,contact_person,license_number,is_verified) VALUES(?,?,?,?,?)',[$d['user_id'],$d['company_name'],$d['contact_person'],$d['license_number'],$d['is_verified']]);}public function update($id,$d){return $this->query('UPDATE hosts SET company_name=?,contact_person=?,license_number=?,is_verified=? WHERE host_id=?',[$d['company_name'],$d['contact_person'],$d['license_number'],$d['is_verified'],$id]);}public function delete($id){return $this->query('DELETE FROM hosts WHERE host_id=?',[$id]);}}
